window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-116c5874ea697237"]={"versions": [{"id": "FIG-116c5874ea697237", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Zuordnungs- und Speicherlayout-Diagramm aus der AUTOSAR Classic Platform Spezifikation des CAN-Treibers (<code>Can</code>). Das Diagramm visualisiert das Mapping zwischen Software-Handles (Hardware Transmit Handles <code>HTH</code> bzw. Hardware Receive Handles <code>HRH</code>) und den physikalischen CAN-Nachrichtenobjekten (<code>Message Objects in CAN Hardware</code>) eines CAN-Controllers bei gemultiplextem Senden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Message Objects in CAN Hardware</strong>: Acht untereinander angeordnete Hardware-Mailboxen bzw. Pufferzeilen, jeweils unterteilt in:\n<ul class=\"fig-list\"><li><code>ID</code>: CAN-Identifier\n</li><li><code>DLC</code>: Data Length Code\n</li><li><code>SDU</code>: Service Data Unit (Nutzdatenbereich)\n</li></ul>\n</li><li><strong>Zuordnungsreferenzen (links)</strong>: Horizontale Referenzlinien für die oberen fünf Einzelobjekte sowie eine geschweifte Klammer für die unteren drei zusammengefassten Hardware-Objekte (ohne textuelle Handle-Zuweisung).\n</li><li><strong>Controller-Scope (oben)</strong>: Eine geschweifte Klammer mit der Beschriftung <code>Message Objects in CAN Hardware</code>, die das gesamte Array der acht Hardware-Puffer umfasst.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt ein statisches Konfigurations- und Zuordnungsschema. Mehrere Hardware-Objekte (die untersten drei Zeilen) sind logisch gebündelt, um gemultiplextes Senden (Multiplexed Transmission) über einen gemeinsamen Transmit-Handle-Pool zu ermöglichen, während die oberen Hardware-Objekte einzeln adressiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht das Prinzip des Multiplexed Transmission im CAN-Treiber. Da die konkrete Zuordnung links unbeschriftet ist, dient die Abbildung als schematische Vorlage: Die Adressierung und Nummerierung von Handles zu Hardware-Objekten ist implementationsspezifisch, wobei mehrere Hardware-Objekte zu einem gemeinsamen HTH für gemultiplexte Übertragung zusammengefasst werden können.</p>"}, {"id": "FIG-b28bee0ff2253bd7", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Zuordnungs- und Speicherlayout-Diagramm aus der AUTOSAR Classic Platform Spezifikation des CAN-Treibers (<code>Can</code>). Das Diagramm visualisiert das Mapping zwischen Software-Handles (Hardware Transmit Handles <code>HTH</code> bzw. Hardware Receive Handles <code>HRH</code>) und den physikalischen CAN-Nachrichtenobjekten (<code>Message Objects in CAN Hardware</code>) eines CAN-Controllers bei gemultiplextem Senden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Objekte (Tabelle)</strong>: Acht Hardware-Pufferzeilen mit den Feldern <code>ID</code> (Identifier), <code>DLC</code> (Data Length Code) und <code>SDU</code> (Payload).\n</li><li><strong>Zugeordnete Handles / Status (links)</strong>:\n<ul class=\"fig-list\"><li>Zeile 1: <code>HRH = 0</code> (Hardware Receive Handle 0)\n</li><li>Zeile 2: <code>HRH = 1</code> (Hardware Receive Handle 1)\n</li><li>Zeile 3: <code>unused</code> (nicht zugewiesenes Hardware-Objekt)\n</li><li>Zeile 4: <code>HRH = 2</code> (Hardware Receive Handle 2)\n</li><li>Zeile 5: <code>HRH = 3</code> (Hardware Receive Handle 3)\n</li><li>Zeilen 6 bis 8: Über eine geschweifte Klammer zusammengefasst und <code>HTH = 4</code> (Hardware Transmit Handle 4) zugewiesen.\n</li></ul>\n</li><li><strong>Controller-Scope (oben)</strong>: Geschweifte Klammer über allen acht Hardware-Objekten ohne Beschriftungstext.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt ein statisches Konfigurations- und Zuordnungsschema. Mehrere Hardware-Objekte (die untersten drei Zeilen) sind logisch gebündelt, um gemultiplextes Senden (Multiplexed Transmission) über einen gemeinsamen Transmit-Handle-Pool zu ermöglichen, während die oberen Hardware-Objekte einzeln adressiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert eine konkrete Beispielbelegung für BasicCAN/FullCAN bzw. Multiplexed Transmission: Vier Hardware-Objekte fungieren als dedizierte Empfangspuffer (<code>HRH = 0</code> bis <code>3</code>), ein Objekt bleibt ungenutzt (<code>unused</code>), und drei Hardware-Objekte werden gemeinsam einem einzelnen Sende-Handle (<code>HTH = 4</code>) zugeordnet. Der CAN-Treiber verteilt ausgehende Sendeanforderungen für <code>HTH = 4</code> auf die drei gemultiplexten Hardware-Transmit-Objekte.</p>"}, {"id": "FIG-223af905dc2b2912", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Zuordnungs- und Speicherlayout-Diagramm aus der AUTOSAR Classic Platform Spezifikation des CAN-Treibers (<code>Can</code>). Das Diagramm visualisiert das Mapping zwischen Software-Handles (Hardware Transmit Handles <code>HTH</code> bzw. Hardware Receive Handles <code>HRH</code>) und den physikalischen CAN-Nachrichtenobjekten (<code>Message Objects in CAN Hardware</code>) eines CAN-Controllers bei gemultiplextem Senden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Objekte (Tabelle)</strong>: Acht Hardware-Pufferzeilen, jeweils unterteilt in die Spalten <code>ID</code>, <code>DLC</code> und <code>SDU</code>.\n</li><li><strong>Zuordnungsreferenzen (links)</strong>: Fünf horizontale Linien für die oberen Hardware-Objekte sowie eine geschweifte Klammer für die unteren drei Hardware-Objekte; sämtliche textuellen Kennzeichnungen (<code>HRH</code>, <code>unused</code>, <code>HTH</code>) fehlen.\n</li><li><strong>Hardware-Rahmen (oben)</strong>: Geschweifte Klammer über der gesamten Hardware-Objekttabelle ohne Beschriftung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt ein statisches Konfigurations- und Zuordnungsschema. Mehrere Hardware-Objekte (die untersten drei Zeilen) sind logisch gebündelt, um gemultiplextes Senden (Multiplexed Transmission) über einen gemeinsamen Transmit-Handle-Pool zu ermöglichen, während die oberen Hardware-Objekte einzeln adressiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als rein schematische Vorlage zur Illustration von Multiplexed Transmission im CAN-Treiber. Da keine konkreten Handles angegeben sind, verdeutlicht die Abbildung abstrakt, dass einzelne Hardware-Objekte separat zugewiesen und eine Gruppe von mehreren Hardware-Objekten (untere drei Zeilen) für gemultiplexte Sendeoperationen zusammengefasst werden.</p>"}], "trans": [{"from": "FIG-116c5874ea697237", "to": "FIG-b28bee0ff2253bd7", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Beschriftungen der Hardware-Objekt-Zuordnungen links hinzugefügt: Zeilen 1, 2, 4 und 5 sind explizit als <code>HRH = 0</code>, <code>HRH = 1</code>, <code>HRH = 2</code> und <code>HRH = 3</code> annotiert; Zeile 3 ist als <code>unused</code> markiert; die zusammengefassten Zeilen 6–8 sind als <code>HTH = 4</code> annotiert.\n</li><li>Übergeordnete Beschriftung <code>Message Objects in CAN Hardware</code> oberhalb der geschweiften Klammer entfernt.\n</li><li>Hintergrundfarbe der Tabellenzellen von Hellgrün/Beige auf Grau geändert.\n</li></ul>"}, {"from": "FIG-b28bee0ff2253bd7", "to": "FIG-223af905dc2b2912", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Alle linksseitigen Zuordnungsbeschriftungen (<code>HRH = 0</code>, <code>HRH = 1</code>, <code>unused</code>, <code>HRH = 2</code>, <code>HRH = 3</code>, <code>HTH = 4</code>) entfernt; an den Referenzlinien verbleiben nur noch Leerlinien bzw. die Klammer ohne Text.\n</li></ul>"}]};
